import {
  SchemaType,
  type GenerationConfig,
  type GenerativeModel,
} from "@google/generative-ai";
import { POS, isPosCode, type PosCode } from "~/data/pos";
import { buildPosGuide } from "~/data/pos_guide";
import type { PosSentence, PosToken } from "~/data/pos_sentences";

/** Parts of speech of the TOCFL 8000 word list, by word. */
export type TocflLexicon = Record<string, PosCode[]>;

/** Generated by `utils/pos/export_tocfl_pos.py`, loaded on first use. */
export async function loadTocflLexicon(): Promise<TocflLexicon> {
  const module = await import("~/data/tocfl_pos.json");
  return module.default as TocflLexicon;
}

/** Longest word looked up in the lexicon, in characters. */
const MAX_WORD_LENGTH = 8;

/**
 * Every word of the TOCFL list found anywhere in `text`, in order of first
 * appearance, with its codes. Overlapping candidates (回 and 回家) are all
 * listed: choosing between them is the model's job.
 */
export function tocflEntriesIn(
  text: string,
  lexicon: TocflLexicon,
): [string, PosCode[]][] {
  const chars = Array.from(text);
  const found = new Map<string, PosCode[]>();
  for (let start = 0; start < chars.length; start++) {
    for (
      let end = start + 1;
      end <= Math.min(chars.length, start + MAX_WORD_LENGTH);
      end++
    ) {
      const word = chars.slice(start, end).join("");
      const codes = lexicon[word];
      if (codes && !found.has(word)) {
        found.set(word, codes);
      }
    }
  }
  return [...found];
}

/**
 * Splits free-form Chinese text into words tagged with TOCFL part of speech
 * codes, using Gemini. The result has the shape of `POS_SENTENCES`, so it
 * renders with `AnnotatedSentence`.
 */

/** Gemini models offered for the breakdown, cheapest first. */
export const POS_BREAKDOWN_MODELS = [
  { name: "gemini-3.5-flash-lite", label: "Flash Lite (fast)" },
  { name: "gemini-3.8-flash", label: "Flash (accurate)" },
  { name: "gemini-3.1-pro-preview", label: "Pro (slow)" },
] as const;

export const DEFAULT_POS_BREAKDOWN_MODEL = "gemini-3.8-flash";

const POS_CODES = Object.keys(POS) as PosCode[];

const GENERATION_CONFIG: GenerationConfig = {
  temperature: 0.2,
  responseMimeType: "application/json",
  responseSchema: {
    type: SchemaType.OBJECT,
    properties: {
      sentences: {
        type: SchemaType.ARRAY,
        items: {
          type: SchemaType.OBJECT,
          properties: {
            en: { type: SchemaType.STRING },
            note: { type: SchemaType.STRING },
            tokens: {
              type: SchemaType.ARRAY,
              items: {
                type: SchemaType.OBJECT,
                properties: {
                  zh: { type: SchemaType.STRING },
                  pos: {
                    type: SchemaType.STRING,
                    format: "enum",
                    enum: POS_CODES,
                  },
                  gloss: { type: SchemaType.STRING },
                  note: { type: SchemaType.STRING },
                },
                required: ["zh"],
              },
            },
          },
          required: ["en", "note", "tokens"],
        },
      },
    },
    required: ["sentences"],
  },
};

/**
 * Builds the prompt. `examples` are already annotated sentences that show the
 * model the conventions of the TOCFL list (word boundaries, what to note).
 */
export function buildPosBreakdownPrompt(
  text: string,
  examples: PosSentence[],
  lexicon: TocflLexicon,
): string {
  const entries = tocflEntriesIn(text, lexicon)
    .map(([word, codes]) => `${word}: ${codes.join(", ")}`)
    .join("\n");
  return `You are a Chinese language expert specializing in Taiwan Mandarin, writing grammar explanations for an English-speaking learner. Split Chinese text into words and label each word with its part of speech (POS), using the TOCFL classification explained below.

${buildPosGuide()}

## How to split and label

- Split into words as the TOCFL 8000 word list does: a word is an entry of a dictionary (書店, 腳踏車, 喜歡, 上課), not a single character, and not a whole phrase. Keep each number, measure word, determiner, aspect particle and pronoun as its own word (這 杯 咖啡, 三 本 書, 買 了).
- The codes are those of the TOCFL word list, which are given below for every word of the list found in the text. When a word is in the list, use one of its listed codes, choosing the one that fits this sentence. In particular, whether a verb takes an object is a property of the word, not of the sentence: 走 and 來 are V even when no object follows them. Only use a code that is not listed when none of the listed ones can describe the word here, and then say why in its note.
- Label a word by what it does in THIS sentence, not by its most common use: 在 + place is Prep, 在 + verb is Adv; 壞 is Vs in 他很壞 but Vp in 電腦壞了.
- A separable verb whose halves stand together is one token (生病, 上課, 睡覺). Only a separable verb that is split by other words becomes two tokens, both labeled with the -sep code of the whole verb, and each one's note says which half of which verb it is (睡 … 覺 of 睡覺).
- Punctuation is its own token with no "pos", "gloss" or "note".
- "gloss" is a short English meaning of the word in this sentence (1-3 words). For grammatical words with no English equivalent, describe the function in parentheses: "(done)", "(question)", "(object)".
- Add a "note" only to the words where it teaches something: why the word has this POS, or what it does grammatically here. Leave it out for plain nouns and obvious words.
- Every character of the input must appear in exactly one token, in the original order and unchanged: do not convert between simplified and traditional characters, fix typos, or drop or add anything.
- Make one entry in "sentences" per sentence of the input. "en" is a natural English translation, and "note" is one or two sentences about what the sentence shows about Chinese parts of speech.

## Examples

${JSON.stringify({ sentences: examples })}

## TOCFL word list entries found in the text

Not every entry is a word of this text: an entry can overlap with a longer word (回 in 回家), or straddle two words.

${entries || "(none)"}

## Task

Break down this text:

${text}`;
}

/** The model's reply breaks the format or the rules of the breakdown. */
export class InvalidPosBreakdownError extends Error {
  constructor(message: string, options?: ErrorOptions) {
    super(`Invalid reply from the AI: ${message}`, options);
    this.name = "InvalidPosBreakdownError";
  }
}

/** Matches a Chinese character: a token without one is punctuation. */
const HAN = /\p{Script=Han}/u;

/** Removes whitespace, which the model may drop or keep. */
function normalize(text: string): string {
  return text.replace(/\s+/g, "");
}

/**
 * Checks the model's reply and converts it to sentences.
 *
 * @throws Error if the reply is malformed, uses an unknown POS code, or its
 * tokens don't add up to the input text
 */
export function parsePosBreakdownResponse(
  text: string,
  responseText: string,
): PosSentence[] {
  let parsed: {
    sentences?: {
      en?: string;
      note?: string;
      tokens?: { zh?: string; pos?: string; gloss?: string; note?: string }[];
    }[];
  };
  try {
    parsed = JSON.parse(responseText) as typeof parsed;
  } catch (e) {
    throw new InvalidPosBreakdownError(`not JSON: ${responseText}`, {
      cause: e,
    });
  }
  if (!Array.isArray(parsed.sentences)) {
    throw new InvalidPosBreakdownError(`no sentences: ${responseText}`);
  }
  const sentences = parsed.sentences.map((sentence): PosSentence => {
    if (!Array.isArray(sentence.tokens) || sentence.en === undefined) {
      throw new InvalidPosBreakdownError(
        `malformed sentence ${JSON.stringify(sentence)}`,
      );
    }
    return {
      en: sentence.en,
      note: sentence.note ?? "",
      tokens: sentence.tokens.map((token): PosToken => {
        if (!token.zh) {
          throw new InvalidPosBreakdownError(
            `token without text ${JSON.stringify(token)}`,
          );
        }
        // Punctuation has no part of speech, whatever the model says
        if (!token.pos || !HAN.test(token.zh)) {
          return { zh: token.zh };
        }
        if (!isPosCode(token.pos)) {
          throw new InvalidPosBreakdownError(
            `unknown POS code "${token.pos}" for ${token.zh}`,
          );
        }
        return {
          zh: token.zh,
          pos: token.pos,
          gloss: token.gloss || undefined,
          note: token.note || undefined,
        };
      }),
    };
  });

  const joined = sentences
    .flatMap((sentence) => sentence.tokens.map((token) => token.zh))
    .join("");
  if (normalize(joined) !== normalize(text)) {
    throw new InvalidPosBreakdownError(
      `the words don't add up to the input text.\nInput: ${normalize(text)}\nWords: ${normalize(joined)}`,
    );
  }
  return sentences;
}

/**
 * Times a reply that breaks the rules is retried. Flash models sometimes close
 * the JSON early (after the first word) or "fix" the input (結婚了 → 結了婚);
 * asking again usually works.
 */
const MAX_ATTEMPTS = 3;

/**
 * Asks Gemini to break down `text`.
 *
 * @throws InvalidPosBreakdownError if every attempt gave an invalid reply
 * @throws Error if the request fails
 */
export async function breakdownPos(
  model: GenerativeModel,
  text: string,
  examples: PosSentence[],
): Promise<PosSentence[]> {
  if (!normalize(text)) {
    throw new Error("No text to break down");
  }
  const lexicon = await loadTocflLexicon();
  const prompt = buildPosBreakdownPrompt(text, examples, lexicon);
  for (let attempt = 1; ; attempt++) {
    const result = await model.generateContent({
      contents: [{ role: "user", parts: [{ text: prompt }] }],
      generationConfig: GENERATION_CONFIG,
    });
    try {
      return parsePosBreakdownResponse(text, result.response.text());
    } catch (e) {
      if (!(e instanceof InvalidPosBreakdownError) || attempt >= MAX_ATTEMPTS) {
        throw e;
      }
      console.warn(`Attempt ${attempt} of ${MAX_ATTEMPTS} failed:`, e.message);
    }
  }
}
